  while (value > 0n) {
    const remainder = Number(value % 58n);
    encoded = BASE58_ALPHABET[remainder] + encoded;
    value /= 58n;
  }

  return BASE58_ZERO.repeat(zeroCount) + encoded;
}

export function decodeBase58(text) {
  if (text.length === 0) {
    return [];
  }

  let zeroCount = 0;
  while (zeroCount < text.length && text[zeroCount] === BASE58_ZERO) {
    zeroCount += 1;
